<body>
  <a class="skip-link" href="#support-form">Skip to form</a>

  <main id="main-content">
    <header class="hero">
      <h1>Contact support</h1>
      <p class="lead">Send our team a message and we’ll get back to you as soon as possible.</p>
    </header>

    <section class="support-card" aria-labelledby="support-form-title">
      <p class="status" id="form-status" role="status" aria-atomic="true"></p>

      <form id="support-form" novalidate>
        <h2 id="support-form-title" class="sr-only">Support contact form</h2>

        <div class="form-field" data-field>
          <label for="full-name">Full name <span class="required" aria-hidden="true">*</span></label>
          <input
            id="full-name"
            name="fullName"
            type="text"
            autocomplete="name"
            required
            aria-describedby="full-name-error"
          />
          <p class="error-text" id="full-name-error" hidden>Full name is required.</p>
        </div>

        <div class="form-field" data-field>
          <label for="email-address">Email address <span class="required" aria-hidden="true">*</span></label>
          <input
            id="email-address"
            name="emailAddress"
            type="email"
            autocomplete="email"
            required
            aria-describedby="email-address-error"
          />
          <p class="error-text" id="email-address-error" hidden>Please enter a valid email address.</p>
        </div>

        <div class="form-field" data-field>
          <label for="phone-number">Phone number</label>
          <input
            id="phone-number"
            name="phoneNumber"
            type="tel"
            autocomplete="tel"
            inputmode="tel"
            aria-describedby="phone-number-help phone-number-error"
          />
          <p class="help-text" id="phone-number-help">Optional. Use a format like +1 555 123 4567 or (555) 123-4567.</p>
          <p class="error-text" id="phone-number-error" hidden>Enter a phone number in the expected format.</p>
        </div>

        <div class="actions">
          <button type="submit">Send message</button>
        </div>
      </form>
    </section>
  </main>

  <script>
    const form = document.querySelector("#support-form");
    const status = document.querySelector("#form-status");
    const fullNameInput = document.querySelector("#full-name");
    const emailInput = document.querySelector("#email-address");
    const phoneInput = document.querySelector("#phone-number");
    const phonePattern = /^\+?[0-9\s().-]{7,}$/;

    const fields = [
      {
        input: fullNameInput,
        error: document.querySelector("#full-name-error"),
        validate: value => value.trim().length > 0,
      },
      {
        input: emailInput,
        error: document.querySelector("#email-address-error"),
        validate: value => value.trim().length > 0 && value.trim() === value && emailInput.validity.valid,
      },
      {
        input: phoneInput,
        error: document.querySelector("#phone-number-error"),
        validate: value => value.trim() === "" || phonePattern.test(value.trim()),
      },
    ];

    function setFieldState(field, isValid) {
      const wrapper = field.input.closest(".form-field");
      field.input.setAttribute("aria-invalid", String(!isValid));
      field.error.hidden = isValid;
      wrapper.classList.toggle("is-invalid", !isValid);
    }

    function validateField(field) {
      const isValid = field.validate(field.input.value);
      setFieldState(field, isValid);
      return isValid;
    }

    fields.forEach(field => {
      field.input.addEventListener("input", () => {
        if (field.error.hidden) {
          return;
        }
        validateField(field);
      });

      field.input.addEventListener("blur", () => {
        validateField(field);
      });
    });

    form.addEventListener("submit", event => {
      event.preventDefault();

      const firstInvalid = fields.find(field => !validateField(field));
      if (firstInvalid) {
        status.textContent = "Please fix the highlighted fields.";
        firstInvalid.input.focus();
        return;
      }

      status.textContent = "Thanks — your message is ready to be sent.";
      form.reset();
      fields.forEach(field => {
        setFieldState(field, true);
      });
    });
  </script>
</body>
</html>
